// Swift 6: strict concurrency ON por padrão

struct User: Sendable {        // valor Sendable: pode cruzar actors
    let id: UUID
    let name: String
}

actor UserCache {
    private var users: [UUID: User] = [:]

    func get(_ id: UUID) -> User? { users[id] }
    func set(_ user: User) { users[user.id] = user }
}

@MainActor
final class UserViewModel {
    private let cache: UserCache
    var displayName: String = ""   // isolado na MainActor

    init(cache: UserCache) { self.cache = cache }

    func load(id: UUID) async {
        // cache é actor: await é obrigatório
        if let u = await cache.get(id) {
            displayName = u.name   // OK: estamos na MainActor
        }
    }
}

import Observation

@Observable
final class CartModel {
    var items: [Item] = []
    var total: Decimal { items.reduce(0) { $0 + $1.price } }

    func add(_ item: Item) { items.append(item) }
}

// Em SwiftUI:
struct CartView: View {
    @State private var cart = CartModel()

    var body: some View {
        VStack {
            ForEach(cart.items) { Text($0.name) }
            Text("Total: \(cart.total)")
            Button("Adicionar") { cart.add(.sample) }
        }
    }
}

enum ParseError: Error {
    case missingField(String)
    case invalidFormat
}

func parseUser(_ data: Data) throws(ParseError) -> User {
    guard let dict = try? JSONSerialization.jsonObject(with: data) as? [String: Any]
    else { throw .invalidFormat }
    guard let name = dict["name"] as? String else { throw .missingField("name") }
    return User(id: UUID(), name: name)
}

// Caller agora sabe o tipo exato:
do {
    let u = try parseUser(data)
} catch .missingField(let f) {
    print("faltou \(f)")
} catch .invalidFormat {
    print("formato invalido")
}

// Recurso com ownership unica (estilo Rust move semantics)
struct FileHandle: ~Copyable {
    private let fd: Int32
    init(path: String) throws { /* open */ self.fd = 0 }
    consuming func close() { /* close(fd) */ }
    deinit { /* garantia de cleanup */ }
}

// Uso: nao pode ser copiado, so movido
func process() throws {
    let handle = try FileHandle(path: "/tmp/x")
    // let copy = handle   // erro de compilacao
    handle.close()
}

